    if (key === "apparent_temperature" && /chill|heat[\s_-]?index/.test(hay)) pen += 10;
    if (/globe|wbgt|soil|water|pool|probe|leaf|\bch[\s_-]?\d|(temperature|humidity)[\s_-]?\d|_\d+$/.test(hay.replace(/_2$/, ""))) pen += 40;
